const ctxActivity=(E,id)=>E.COMPANION_ACTIVITIES.find(a=>a.id===id);
function previousNote(v,{E,esc}){
 if(!v.previous)return '';
 const a=ctxActivity(E,v.previous.activity),label=a.steps[0].options.find(o=>o.id===v.previous.answers[0]).label;
 return `<p class="companion-recall">Last time, Day ${v.previous.day}: ${esc(label.toLowerCase())}. ${esc(v.person)} remembers.</p>`;
}
export function companionCard(s,id,ctx){
 const {E,esc}=ctx,v=E.companionInvitation(s,id);if(!v?.unlocked)return '';
 const active=v.active,away=active&&active.mallId!==s.mallId;
 const message=v.waiting?'A new invitation arrives tomorrow.':v.doneToday?'A shared afternoon is already in your memory book today. Fresh company awaits tomorrow.':v.busy?'Continue or leave your current shared activity before choosing another friend.':v.activity.scene;
 return `<section class="companion-card"><small>AFTER THE STORY · ${esc(v.person.toUpperCase())}</small><h3>${esc(v.activity.title)}</h3><p>${esc(v.callback)}</p>${previousNote(v,ctx)}<p>${esc(message)}</p>${active?`<p>${active.answers.length} / ${v.activity.steps.length} choices saved · ${esc(E.mallById(active.mallId).name)}</p><button class="button orange wide" data-action="${away?'companion-route':'companion-resume'}" data-id="${id}">${away?'Return to '+esc(E.mallById(active.mallId).name):'Continue our shared activity'} ↗</button>`:!v.waiting&&!v.doneToday&&!v.busy?`<button class="button orange wide" data-action="companion-begin" data-id="${id}">Spend a little time · ${v.activity.minutes} min</button>`:''}<p class="story-note">Free · no purchase needed · +20 XP and a little rest when finished. One shared memory per day, across all friends. Choices save as you go; time is used only when you finish.</p></section>`;
}
export function companionBoard(s,ctx){
 const {E,esc}=ctx,all=E.companionInvitations(s).filter(v=>v.unlocked),active=s.companionVisit;
 return `<section class="companion-board" aria-labelledby="companion-heading"><div class="eyebrow">AFTER THE STORY</div><h3 id="companion-heading">An afternoon with a familiar face.</h3><p>Five chapters are a beginning. Return for shared activities that remember the direction you chose together.</p>${all.length?`<div class="companion-invitations">${all.map(v=>`<article><strong>${esc(v.person)} · ${esc(v.activity.title)}</strong><p>${v.waiting?'A fresh invitation tomorrow.':v.doneToday?'Your next invitation waits tomorrow.':v.active?'Continue your saved choices at '+esc(E.mallById(v.active.mallId).name)+'.':v.busy?'Another shared activity is underway.':esc(v.callback)}</p><button class="button secondary" data-action="companion-route" data-id="${v.id}">${v.active?'Continue with':'Visit'} ${esc(v.person)} ↗</button></article>`).join('')}</div>`:'<p class="hint">Finish all five local chapters with any friend to open their invitations the next day. Each friend has two shared activities, with no new purchase required.</p>'}${active?'<p class="story-note">Your shared activity stays saved if you close it, sleep or travel. Return to its original mall to finish.</p>':''}${s.companionMemories.length?`<details class="companion-memory-book"><summary>Your shared afternoons · ${s.companionMemories.length} saved</summary>${s.companionMemories.slice().reverse().map(m=>`<p><span>Day ${m.day} · ${esc(E.LOCALS.find(n=>n.id===m.person).name)} · ${esc(ctxActivity(E,m.activity).title)}</span><button class="button secondary" data-action="companion-memory" data-id="${m.day}">Read memory · Day ${m.day}</button></p>`).join('')}</details>`:''}</section>`;
}
function answersHTML(activity,answers,esc){return `<ol class="companion-replies">${answers.map((id,i)=>{const o=activity.steps[i].options.find(v=>v.id===id);return `<li><strong>${esc(o.label)}</strong><p>${esc(o.response)}</p></li>`;}).join('')}</ol>`;}
export function companionSession(s,ctx){
 const {E,esc}=ctx;
 const r=s.companionVisit,v=E.companionInvitation(s,r.person),a=v.activity,index=r.answers.length,step=a.steps[index];
 const response=index?a.steps[index-1].options.find(o=>o.id===r.answers[index-1]).response:a.scene;
 return `<div class="modal-body companion-session"><p class="companion-recall">${esc(v.callback)}</p>${previousNote(v,ctx)}<div class="companion-scene" aria-hidden="true"><span>${esc(v.person[0])}</span><i>✦</i><span>${esc((s.playerName||'S')[0])}</span></div><p id="companion-response">${esc(response)}</p><small>${index} / ${a.steps.length} choices saved · ${a.minutes} min when finished · Free</small><h3 id="companion-question" tabindex="-1" aria-describedby="companion-response">${esc(step?step.text:'An afternoon to keep.')}</h3>${step?`<div class="companion-choices" role="group" aria-labelledby="companion-question">${step.options.map(o=>`<button class="button secondary" data-action="companion-answer" data-index="${index}" data-id="${o.id}">${esc(o.label)}</button>`).join('')}</div>`:`${answersHTML(a,r.answers,esc)}<p>Save this afternoon for <strong>+20 XP</strong> and a little stamina recovery. This uses <strong>${a.minutes} game minutes</strong>. No game money is charged.</p><button class="button orange wide" data-action="companion-finish">Keep this memory · ${a.minutes} min</button>`}<p class="story-note">Close to continue later. Your answers are saved. Or leave this activity to choose another invitation; no time or reward is used.</p><button class="text-button" data-action="companion-leave">Leave this activity</button></div>`;
}
export function companionMemory(s,m,{E,esc}){
 const a=ctxActivity(E,m.activity),v=E.companionInvitation(s,m.person);
 return `<div class="modal-body companion-session"><p>Day ${m.day} · ${esc(E.mallById(m.mallId).name)} · with ${esc(v.person)}</p><p>${esc(v.callback)}</p><p>${esc(a.scene)}</p>${answersHTML(a,m.answers,esc)}<p class="hint">A shared afternoon, safely remembered. Its reward has already been collected.</p><button class="button secondary wide" data-action="local-return" data-id="${m.person}">Back to ${esc(v.person)}</button></div>`;
}
